"""English lessons 21, 23-26, 29, 30 and the remaining workplace skills."""
from scripts.case_authoring.schema import A, L, O

PRO = 'Fluent, natural professional English. Direct, and free of corporate slogans.'

LESSONS = [
 L('english-21', 'interview', 'advanced', 'A fictional first-round interview for a {{role}} role at {{company}}.',
   'You are interviewing for a {{role}} role at {{company}}. {{name}}, the hiring manager, opens with "tell me about yourself". Use your own real background.',
   'Welcome. To begin, could you tell me about yourself and why this role interests you?',
   'Job candidate', 'You are a candidate in a first-round interview.', 'Give a short professional summary, connect your experience to this role, and give one specific example when asked.',
   '{{name}} understands your background, why this role fits, and has heard one specific example.',
   [A('{{name}}', 'Hiring manager', 'Would be your manager', 'To find out quickly whether this person fits, and why they want this job.', 'Courteous and focused, with little patience for a life story.', PRO, ['Ask how that relates to this role', 'Ask for one specific example', 'Never supply details of the candidate\'s experience'], ['role', 'company', 'team', 'experience'])],
   ['The role is {{role}} at {{company}}.', ("The candidate's background comes from the candidate. {{name}} knows only what the candidate says.", 'public'), ('The role mainly involves {{duties}}.', 'p1')],
   [O('Hear a focused summary.', 'The learner gives a brief, relevant summary of experience.', "I've worked in support for three years, currently leading a small team.", ['Give me the short version: who are you, professionally?', 'What do you do at the moment?'],
      "This is a job interview, and I've asked you to introduce yourself. Say what you do now and your main experience, in two sentences.", 'Present, past and why here, in a few sentences.', 'Reciting your whole life story', 'Keep it to what matters for this job.', "I've worked in support for three years, and I currently lead a small team.", 'Say: I currently work as.', 'vocabulary'),
    O('Connect the experience to the role.', 'The learner links their experience to this particular role.', 'This role interests me because it builds on my work with customers.', ['Why this role, in particular?', 'How does that help you do this job?'],
      'Now say why this role fits you. Start with: This role interests me because.', 'A reason specific to this job, not any job.', "Saying: It's a great company", 'Connect one thing you have done to one thing the job needs.', 'This role interests me because it builds on my customer experience.', 'Say: This role interests me because.', 'comprehension'),
    O('Hear a specific example.', 'The learner gives a concrete example or achievement.', 'For example, I reduced waiting times by reorganizing our shifts.', ['Can you give me one example of that?', "What's an achievement you are proud of?"],
      'Give me one real example from your experience. Start with: For example.', 'A real example is worth more than any adjective.', "Saying: I'm a hard worker", 'Show it, with one real story.', 'For example, I reduced our waiting times by reorganizing the shifts.', 'Say: For example, I.', 'grammar')],
   'Thank you. That gives me a good first picture.',
   [{'name': 'Saima', 'role': 'team coordinator', 'company': 'Northline Logistics', 'duties': 'planning shifts and handling customer escalations'}, {'name': 'Peter', 'role': 'junior analyst', 'company': 'Marlow Foods', 'duties': 'preparing weekly sales reports and checking data'}]),

 L('english-23', 'panel', 'advanced', 'A fictional funding meeting where the learner and a teammate propose an idea to a decision-maker.',
   'You and your teammate {{mate}} want {{name}}, the director, to fund {{proposal}}, at {{cost}}. Your evidence: {{evidence}}. Limitation: {{limit}}. Recommend early, use evidence, and answer an objection.',
   'You have five minutes to convince me that {{proposal}} is worth funding. Go ahead.',
   'Presenter', 'You are presenting a funding proposal with a teammate.', 'State your recommendation early, use your evidence, and answer an objection. Your teammate can help if you bring them in.',
   '{{name}} has a clear recommendation, your evidence, and a real answer to the main objection.',
   [A('{{name}}', 'Decision-maker', 'Director who controls the budget', 'A proposal that is worth the money, and honesty about the risks.', 'Sharp, fair and short of time.', PRO, ['Ask for the bottom line', 'Raise the cost objection', 'Ask what happens if it fails'], ['budget', 'cost', 'decision', 'money', 'fund'], 'Has been let down by an over-promised project before.'),
    A('{{mate}}', 'AI teammate', 'On your side; helped to prepare the proposal', 'To support your case, without taking over.', 'Helpful and factual.', PRO, ['Add a supporting fact only if asked or if things stall', 'Never speak for the whole team'], ['evidence', 'data', 'detail'])],
   ['The proposal is {{proposal}}. It costs {{cost}}.', 'The evidence is: {{evidence}}.', 'A limitation is: {{limit}}.', ('{{name}} is worried about value for money.', 'p1')],
   [O('Hear the recommendation early.', 'The learner states the recommendation near the start.', 'I recommend we fund a three-month trial.', ['Bottom line: what are you asking for?', 'What do you want me to approve?'],
      'You have to convince me to fund this. Tell me first what you recommend.', 'Recommendation first, reasons after.', 'Building up slowly to the point', 'Say: I recommend, in your first sentence.', 'I recommend we fund a three-month trial.', 'Say: I recommend.', 'vocabulary'),
    O('Test the evidence.', 'The learner supports the case with the supplied evidence.', 'The evidence shows that errors fell during the pilot.', ['What evidence do you have?', 'Why should I believe that will work?'],
      'Give me your evidence from the brief. You can also ask {{mate}} to add a detail.', 'Using real evidence, and naming its limits.', 'Claiming more than the evidence shows', 'Say: The evidence shows, and name a limit.', 'The evidence shows errors fell, though it is only one team so far.', 'Say: The evidence shows.', 'grammar', second=('p2', 'I can add one detail from the pilot, if that helps.')),
    O('Handle the objection.', 'The learner responds to an objection directly.', 'I understand that concern; however, a limited trial reduces the risk.', ['{{cost}} is a lot of money. Why should I spend it on this?', 'What if it fails?'],
      'I have raised an objection about the cost. Answer it directly. Start with: I understand that concern.', 'Accepting the objection, and then answering it.', 'Getting defensive, or repeating yourself', 'Say: I understand that concern; however.', 'I understand that concern; however, a short trial limits the risk.', 'Say: I understand that concern.', 'comprehension')],
   "All right. You've made a fair case. I'll take that forward.",
   [{'name': 'Farah', 'mate': 'Daniel', 'proposal': 'a new customer support tool', 'cost': 'USD 15000', 'evidence': 'in a small pilot, average reply time fell from 9 hours to 5 hours', 'limit': 'the pilot covered only one team'},
    {'name': 'James', 'mate': 'Hira', 'proposal': 'a staff mentoring programme', 'cost': 'USD 8000', 'evidence': 'new staff in last year\'s trial reached full productivity two weeks earlier', 'limit': 'the trial had only ten people'}]),

 L('english-24', 'negotiation', 'advanced', 'A fictional client meeting about changing the scope and timing of a project.',
   'You manage {{project}}. {{a}}, the client director, wants it {{earlier}} earlier with no extra budget. {{b}} is the client\'s technical lead. You could {{options}}. Find out why, offer a fair trade, and confirm what is agreed.',
   'We need {{project}} {{earlier}} earlier, and we cannot increase the budget.',
   'Project manager', 'You are the project manager, and you can agree changes to scope and timing.', 'Find out what really matters to the client, offer a fair trade-off rather than simply saying yes, and confirm the agreement.',
   'You know their real priority, you agreed a trade, and you have confirmed exactly what changes.',
   [A('{{a}}', 'Client director', 'Your client', 'To hit the date, without paying more.', 'Firm and commercially minded, and reasonable when given a real trade.', PRO, ['State the demand firmly at first', 'Accept a trade only if the key priority is protected', "Don't accept vague promises"], ['date', 'budget', 'deadline', 'priority', 'launch'], '{{need}}'),
    A('{{b}}', 'Client technical lead', 'Works for the client', 'A delivery that actually works, even if some features come later.', 'Pragmatic, and more flexible on scope than the director.', PRO, ['Say which features could wait, if asked', 'Warn about quality risks'], ['scope', 'feature', 'quality', 'technical', 'testing'])],
   ['The project is {{project}}.', 'The client wants it {{earlier}} earlier, and will not increase the budget.', 'The learner may {{options}}.', ('{{need}}', 'p1', 1), ('{{later}} could come after launch.', 'p2')],
   [O('Reveal the real priority.', 'The learner asks a question that uncovers the underlying priority.', 'What matters most about that date?', ['Are you going to ask why we need it earlier?', 'Why do you think the date matters?'],
      "I've made a demand. Before you answer, find out why. Ask what matters most about the date.", 'Asking why, before you say yes or no.', 'Saying yes or no straight away', 'Ask: What matters most about that date?', 'What matters most about that date? What happens if we miss it?', 'Say: Why does the date matter?', 'comprehension', min_turns=1),
    O('Hear a trade rather than a concession.', 'The learner offers a conditional trade-off.', 'If we move some features to a second phase, we could hit that date.', ['So can you do it or not?', 'What are you actually offering?'],
      'Now offer me a trade. Start with: If we. You could change scope or timing, as in your brief.', 'Linking what you give to what you get.', 'Agreeing to everything, or refusing everything', 'Say: If we, then we could.', 'If we move two features to a second phase, we could hit that date.', 'Say: If we.', 'vocabulary', second=('p2', 'Some of the features could wait, if that gets us a working launch.')),
    O('Confirm what is agreed.', 'The learner confirms the agreement explicitly.', "To confirm: we launch the core by the new date, and the rest comes after.", ['So what exactly have we agreed?', 'Can you put that in one sentence?'],
      'Now confirm exactly what we agreed. Start with: To confirm.', 'Saying the agreement aloud, so that it can\'t be misunderstood.', 'Ending on: That should be fine', 'Say what changes, and who does what.', 'To confirm: we launch the core on the new date, and the rest follows a month later.', 'Say: To confirm.', 'grammar')],
   'Good. That works for us. Please send that in writing.',
   [{'a': 'Helen', 'b': 'Raza', 'project': 'the new booking system', 'earlier': 'two weeks', 'options': 'move features to a second phase, or reduce testing scope with the client\'s agreement', 'need': 'A trade show on the new date is where the system will be shown to customers.', 'later': 'The reporting screens'},
    {'a': 'Victor', 'b': 'Amna', 'project': 'the staff training portal', 'earlier': 'three weeks', 'options': 'launch to one department first, or postpone the mobile version', 'need': 'A new group of staff starts on the new date, and they need the portal for their first day.', 'later': 'The mobile version'}]),

 L('english-25', 'meeting', 'advanced', 'A fictional discussion with a project manager who is confident in a team decision.',
   '{{name}}, your project manager, decided to {{decision}}. You think that is a mistake, because {{evidence}}. Challenge it without damaging the relationship, and offer an alternative: {{alternative}}.',
   "The team has agreed to {{decision}}, so I don't see a reason to reopen this.",
   'Team member', 'You disagree with your project manager, and you want to keep a good working relationship.', 'Acknowledge common ground, explain your concern with evidence, and offer an alternative.',
   '{{name}} has heard your concern and evidence, has an alternative to consider, and still respects you.',
   [A('{{name}}', 'Project manager', 'Your manager on this project', 'To keep the project moving, and not to reopen every decision.', 'Confident, a little impatient, and persuaded only by evidence.', PRO, ['Defend the decision at first', 'Accept evidence, and reject opinion', 'Ask for a practical alternative'], ['decision', 'team', 'plan', 'evidence', 'project'], 'Is under pressure to show progress, and fears looking indecisive.')],
   ['The decision is to {{decision}}.', 'The evidence is that {{evidence}}.', 'A possible alternative is {{alternative}}.', ('{{name}} made the decision under pressure from senior management to show progress.', 'p1', 1)],
   [O('Hear common ground first.', 'The learner acknowledges common ground or the manager\'s goal.', 'I agree we need to move fast.', ['So what is your issue?', 'Are you against moving quickly?'],
      "You disagree with me, but you still want to work together. Start by saying what you agree with. You can say: I agree that.", 'Starting with what you share lowers defences.', 'Opening with: That is wrong', 'Say: I agree that, or: We both want.', 'I agree we need to move fast, and I want this to succeed.', 'Say: I agree that.', 'vocabulary'),
    O('Hear the concern with evidence.', 'The learner explains the concern, using evidence.', 'My concern is that we saw this fail last time, because...', ['That is an opinion. What makes you say that?', 'What is your concern, exactly?'],
      'Now tell me your concern, and use the evidence in your brief. Start with: My concern is.', 'Evidence, not opinion, and about the plan, not the person.', 'Saying: I just feel', 'Say: My concern is, then: because.', 'My concern is the risk, because of what happened in the last release.', 'Say: My concern is.', 'grammar'),
    O('Hear an alternative.', 'The learner proposes a practical alternative.', 'An alternative would be to pilot it with one team first.', ['So what would you do instead?', 'If not this, then what?'],
      'Now give me an alternative. Start with: An alternative would be.', 'Bringing a solution as well as a problem.', 'Criticizing, with nothing to offer instead', 'Say: An alternative would be.', 'An alternative would be to pilot it with one team first.', 'Say: An alternative would be.', 'comprehension')],
   "All right, I hear you. Let's look at that properly. Thanks for raising it directly.",
   [{'name': 'Karen', 'decision': 'move every customer to the new system in one weekend', 'evidence': 'last year\'s one-weekend move caused two days of outages', 'alternative': 'moving one customer group first'},
    {'name': 'Faisal', 'decision': 'cut the testing phase in half to meet the date', 'evidence': 'most serious defects last quarter were found in the second half of testing', 'alternative': 'keeping full testing for the payment features only'}]),

 L('english-26', 'meeting', 'advanced', 'A fictional feedback conversation between two coworkers, with a teammate present, after a client meeting.',
   'You and {{name}} attended a client meeting yesterday. {{name}} asked for your feedback. You noticed that {{observation}}. The effect was that {{impact}}. {{mate}}, a teammate who was also there, has joined you.',
   'You said you had some feedback on yesterday\'s client meeting. Are you ready to discuss it?',
   'Coworker', 'You are giving a coworker feedback they asked for.', 'Describe what you observed, explain its impact, and agree one improvement.',
   '{{name}} knows exactly what you noticed and why it mattered, and you both agree one change.',
   [A('{{name}}', 'Coworker', 'Works with you; asked for this feedback', 'Useful feedback, though it stings a little.', 'Open, but a bit defensive at first.', PRO, ['Ask for a specific example if the feedback is vague', 'Explain your reason once, then listen'], ['meeting', 'client', 'feedback', 'next time'], 'Was very nervous in that meeting.'),
    A('{{mate}}', 'AI teammate', 'Also attended the meeting', 'To support a fair and useful conversation.', 'Calm, and only adds facts.', PRO, ['Confirm facts when asked', 'Do not give the feedback for the learner'], ['saw', 'noticed', 'remember'])],
   ['You both attended a client meeting yesterday.', 'What you noticed: {{observation}}.', 'The effect: {{impact}}.', ('{{name}} did this because of nerves about the client.', 'p1', 1)],
   [O('Hear a specific observation.', 'The learner gives a specific observation, not a judgement.', 'When the client asked about cost, I noticed that you moved on quickly.', ['Sure, what did you notice?', 'Can you give me a specific example?'],
      'I asked for feedback. Tell me one specific thing you saw. Start with: I noticed that.', 'Something a camera could have seen, not a judgement of the person.', "Saying: You were unprofessional", 'Say: When, then: I noticed.', 'When the client asked about cost, I noticed that you moved on quickly.', 'Say: I noticed that.', 'vocabulary'),
    O('Understand the impact.', 'The learner explains the impact.', 'The impact was that the client seemed unsure.', ['Why does that matter?', 'Okay, was that really a problem?'],
      'Now tell me why it mattered. Start with: The impact was.', 'Explaining why it matters makes the feedback useful.', 'Stopping at the observation', 'Say: The impact was, or: As a result.', 'The impact was that the client seemed unsure, and asked again later.', 'Say: The impact was.', 'grammar', second=('p2', 'I noticed the client asked about that again near the end, too.')),
    O('Agree one improvement.', 'The learner agrees one specific improvement.', 'Next time, could we agree who answers the cost questions?', ['So what should I do differently?', 'What would you suggest?'],
      'Now agree one change for next time. Start with: Next time, could we.', 'One achievable change, agreed together.', 'A long list of everything', 'Pick one change. Say: Next time.', 'Next time, could we agree before the meeting who answers cost questions?', 'Say: Next time.', 'comprehension')],
   'Thanks. That was useful, and I will do that next time.',
   [{'name': 'Omar', 'mate': 'Lena', 'observation': 'Omar spoke over the client twice when they raised concerns', 'impact': 'the client stopped raising questions'},
    {'name': 'Tina', 'mate': 'Asad', 'observation': 'Tina moved on quickly when the client asked about cost', 'impact': 'the client asked the same question again at the end, and seemed unsure'}]),

 L('english-29', 'meeting', 'advanced', 'A fictional video call with international project partners after a misunderstanding.',
   'Your team\'s message said the work would be done "{{phrase}}". {{a}}\'s team took that to mean {{a_view}}. Clear up what went wrong with {{a}} and {{b}}, and agree how to communicate from now on.',
   'Our teams understood your last message very differently. How do we stop that from happening again?',
   'Project lead', 'You lead the project team and are working with international partners.', 'Clarify what people meant, avoid idioms and vague language, check understanding, and agree a communication rule.',
   'Everyone understands what went wrong, and you have agreed one clear communication rule.',
   [A('{{a}}', 'Regional partner', 'Leads the partner team abroad', 'Clear, literal communication, so that the team can plan.', 'Polite and direct, and tells you when something is unclear.', 'Precise international English. Asks what idioms mean.', ['Ask what an idiom means', 'Say how your team understood it'], ['deadline', 'message', 'meant', 'understood'], 'Was embarrassed in front of a local client because of this.'),
    A('{{b}}', 'Partner team member', 'Works with {{a}}', 'To know exactly who does what, and when.', 'Quiet and careful. Agrees politely even when unsure, unless asked directly.', 'Careful, precise English. Says yes politely, even when unsure.', ['Say yes without being sure, unless asked directly', 'Answer honestly when asked'], ['time', 'timezone', 'understand', 'team'])],
   ['The earlier message said the work would be done "{{phrase}}".', "{{a}}'s team took that to mean {{a_view}}.", 'The learner\'s team meant {{meant}}.', ('{{a}} was embarrassed in front of a local client because of this.', 'p1', 1)],
   [O('Have the meaning clarified.', 'The learner clarifies what was meant, or asks what the others understood.', 'When you read that, what did you understand by it?', ['What did you actually mean by that?', 'How were we supposed to read it?'],
      'There was a misunderstanding. Ask what we understood, or say clearly what your team meant.', 'Finding out what each side thought, without blame.', 'Insisting that it was obvious', 'Ask: What did you understand? Then say what you meant.', 'When you read "{{phrase}}", what did you understand by it?', 'Ask: What did you understand?', 'vocabulary', signal=r"\b(?:do you mean|when you say|when you read|could you clarify|to clarify|did you understand|you understood|we meant|what we meant|what did you)\b"),
    O('Have understanding checked.', 'The learner checks shared understanding, including with the quieter person.', '{{b}}, is that the same as how you understood it?', ['Yes, yes. I think that is fine.', 'That seems okay, I suppose.'],
      '{{b}} said yes, but may not be sure. Check directly. You can ask: {{b}}, how do you understand it?', 'Asking people to say it back, as a polite yes may not mean they understood.', 'Accepting a polite yes', 'Ask them to say it in their own words.', '{{b}}, could you tell me how you understand the plan?', 'Ask {{b}} a direct question.', 'comprehension', driver=2, signal=r"\b(?:is that correct|have i understood|same understanding|does that mean|how you understood|how do you understand|you understand|in your own words|same as)\b"),
    O('Agree a norm.', 'The learner proposes a clear communication norm.', "Let's agree that from now on, we always write the date and time zone.", ['So what do we do differently from now on?', 'What is the rule, then?'],
      "Propose one clear rule. Start with: Let's agree that.", 'A rule simple enough to check.', 'Saying: We will communicate better', "Say: Let's agree that, from now on.", "Let's agree that from now on, we write an exact date and time zone.", "Say: Let's agree.", 'grammar')],
   'Good. That is clear for both teams. Thank you.',
   [{'a': 'Kenji', 'b': 'Yuki', 'phrase': 'by end of play Friday', 'a_view': 'Friday morning, their time', 'meant': 'Friday at 6 pm, UK time'},
    {'a': 'Lucia', 'b': 'Marco', 'phrase': 'in the next couple of days', 'a_view': 'exactly two days', 'meant': 'within about a week'}]),

 L('english-30', 'meeting', 'advanced', 'A fictional decision meeting with an executive sponsor and two stakeholders.',
   'You are recommending what to do about {{issue}}. Your options are {{options}}. Your evidence: {{evidence}}. {{a}} is the executive sponsor, and {{b}} leads the affected team. Lead the discussion to a decision.',
   'We are ready for your recommendation on {{issue}}. Please lead us through it.',
   'Project lead', 'You are leading a decision meeting with a sponsor and a team lead.', 'Make a supported recommendation, respond to both viewpoints, and summarise the decision and next steps.',
   'There is a decision, both viewpoints have been answered, and everyone knows the next steps.',
   [A('{{a}}', 'Executive sponsor', 'Owns the budget and the final decision', 'A clear recommendation she can defend to the board.', 'Decisive, and tests every assumption.', PRO, ['Ask what you are recommending', 'Ask about the cost of being wrong'], ['cost', 'decision', 'board', 'risk', 'budget'], 'Must report the decision to the board this month.'),
    A('{{b}}', 'Team lead', 'Leads the team affected by the decision', 'A plan that the team can actually deliver.', 'Protective of the team, and practical.', PRO, ['Raise the workload on your team', 'Ask who will do the extra work'], ['team', 'workload', 'people', 'capacity', 'staff'])],
   ['The issue is {{issue}}.', 'The options are {{options}}.', 'The evidence is: {{evidence}}.', ('{{a}} must report the decision to the board this month.', 'p1'), ('{{b}}\'s team is already at full capacity this quarter.', 'p2')],
   [O('Hear a supported recommendation.', 'The learner makes a recommendation with a reason.', 'My recommendation is option A, because the evidence shows...', ['So what do you recommend?', 'What would you do, and why?'],
      "You're leading this meeting. Tell us which option you recommend and why. Start with: My recommendation is.", 'A clear choice, with the reason attached.', 'Listing options with no recommendation', 'Say: My recommendation is, then: because.', 'My recommendation is the first option, because the evidence shows the risk is lower.', 'Say: My recommendation is.', 'vocabulary', signal=r"\b(?:my recommendation|i recommend|we should|i propose)\b"),
    O('Have both views answered.', 'The learner responds to the sponsor\'s and the team lead\'s viewpoints.', 'I hear both perspectives: the cost concern and the workload.', ['And what about the cost if this goes wrong?', 'And what about the people who have to do this work?'],
      'We have different concerns: cost and workload. Respond to each of us.', 'Answering each person\'s actual concern.', 'Answering only the most senior person', 'Name each concern and answer it.', 'I hear both perspectives. On cost, ...; on workload, ...', 'Answer one concern by name.', 'comprehension', second=('p2', 'Before we go further, my team is at full capacity this quarter. Who does this work?'), min_turns=2),
    O('Hear the summary and next steps.', 'The learner summarises the decision and the next steps.', 'To summarise: we decided on the pilot; next steps are...', ['So where have we ended up?', 'What do I tell the board?'],
      'Close the meeting. Say what we decided, and the next steps. Start with: To summarise.', 'Closing with a decision, owners and dates.', 'Ending with: We will think about it', 'Say: To summarise, we decided.', 'To summarise, we decided on the pilot. Next steps: I will send the plan on Friday.', 'Say: To summarise.', 'grammar')],
   'Thank you. That is a clear decision, and I can take that to the board.',
   [{'a': 'Rebecca', 'b': 'Imran', 'issue': 'the failing customer support system', 'options': 'replacing it this year, or repairing it and replacing it next year', 'evidence': 'it failed four times last quarter, and repairs cost a third of what a replacement costs'},
    {'a': 'Sadia', 'b': 'Luke', 'issue': 'the delay in opening the second warehouse', 'options': 'opening late with full staff, or opening on time with reduced hours', 'evidence': 'hiring is six weeks behind, and customers mostly order in the mornings'}]),

 L('activity-active-listening', 'customer', 'intermediate', 'A fictional support call about a billing problem.',
   '{{name}} is calling about {{problem}}. Your job in this call is to listen before you solve anything: acknowledge, ask clarifying questions, and summarise.',
   "Hello. I'm really frustrated, because {{problem}}, and I've explained this before.",
   'Support specialist', 'You are a support specialist on a call with an upset customer.', 'Acknowledge what the customer says, ask clarifying questions to get the facts, and summarise before suggesting anything.',
   '{{name}} agrees that your summary is right.',
   [A('{{name}}', 'Customer', 'A long-standing customer', 'To be understood the first time, without repeating everything.', 'Frustrated, and quickly calmer when really listened to.', 'Natural spoken English. Gives details only when asked.', ['Share details only when asked', "Say 'that's not quite it' if a summary is wrong"], ['bill', 'charge', 'account', 'called'], '{{need}}')],
   [('The problem is that {{problem}}.', 'public'), ('The details are: {{details}}', 'p1'), ('{{need}}', 'p1', 1)],
   [O('Feel acknowledged.', 'The learner acknowledges the customer specifically.', 'I hear you, and having to explain it again is frustrating.', ['I am tired of explaining this.', 'Is anyone listening to me?'],
      "You are listening to me, an upset customer. Don't solve anything yet. First, show you understand how I feel.", 'Naming the actual frustration.', 'Only saying: I understand', 'Mention what they actually said.', 'Having to explain this again must be really frustrating.', 'Say what they are frustrated about.', 'acknowledgement', desc='Acknowledge what the customer said', signal=r"\b(?:i hear|understand|frustrat|sounds|must be|sorry|appreciate)\b"),
    O('Give the facts when asked.', 'The learner asks open questions that bring out the facts.', 'Could you tell me when you first noticed it?', ['What else do you need to know?', 'I can tell you more, if you ask.'],
      'Ask me for the details. Start with: Could you tell me, or: When did.', 'Open questions bring out what you need.', 'Asking something already answered', 'Start with: What, when, which or how.', 'Could you tell me when you first noticed it?', 'Ask one question beginning with: When.', 'clarifying questions', desc='Ask clarifying questions', signal=r"\b(?:could you|can you|when did|when was|which|what (?:did|was|happened)|how (?:many|much|long|often))\b"),
    O('Hear the summary.', 'The learner accurately summarises the issue back.', 'So you were charged twice in March, and nobody called back.', ['Do you understand it now?', 'Can you tell me what you heard?'],
      'Now say back what I told you, so I know that you heard. Start with: So what you are saying is.', 'A short, accurate summary, before you solve anything.', 'Moving to a solution with no summary', "Say: So, and repeat the key facts.", 'So you were charged twice in March, and nobody called you back. Is that right?', 'Say one fact back: So you.', 'summarising', desc='Summarise before you solve', signal=r"\b(?:so you|if i understand|to confirm|in other words|what you(?:'re| are) saying|let me (?:check|make sure))\b")],
   "Yes. That's it exactly. Thank you for listening.",
   [{'name': 'Mr Aziz', 'problem': 'I have been charged twice this month', 'details': 'two charges of 45 appeared on the 3rd and the 5th of this month; you called once last week and were promised a callback', 'need': 'Rent is due soon, and the double charge has left the account short.'},
    {'name': 'Ms Clarke', 'problem': 'my delivery tracking has not updated for a week', 'details': 'the order was placed nine days ago; tracking last changed seven days ago', 'need': 'The parcel is a gift for an elderly parent\'s birthday this weekend.'}]),

 L('activity-conflict-resolution', 'colleague', 'intermediate', 'A fictional disagreement between colleagues over a shared resource.',
   'Your team booked {{resource}} for {{your_use}}. {{name}} urgently wants it for {{their_use}} at the same time. {{alternative}} Calm things down and find a fair solution.',
   "I need {{resource}} for {{their_use}}, and your team has blocked it. This can't wait.",
   'Colleague', 'You are a colleague in a disagreement about a shared resource.', 'Lower the tension, show you understand the concern, and work out a fair solution together.',
   'The tension has come down, and you both accept a specific solution.',
   [A('{{name}}', 'Colleague', 'From another team', 'To get what is needed for their urgent work.', 'Stressed and sharp, and reasonable once heard.', 'Direct, natural workplace English. No insults.', ['Start sharply', 'Soften when your concern is taken seriously', 'Reject one-sided solutions'], ['room', 'booking', 'urgent', 'client', 'time'], '{{need}}')],
   ['Your team booked {{resource}} for {{your_use}}.', '{{name}} wants it for {{their_use}}.', '{{alternative}}', ('{{need}}', 'p1', 1)],
   [O('Calm the situation.', 'The learner lowers the tension rather than arguing.', "Let's work this out together. I can see this is urgent.", ['So you are just going to keep it?', 'Are you even listening?'],
      "We're arguing. You don't need to win. Say something calm, like: Let's work this out together.", 'A calm tone, and no blame.', 'Answering sharpness with sharpness', "Say: Let's work this out.", "Let's work this out together.", "Say: Let's work this out.", 'de-escalation', desc='De-escalate the tension', signal=r"\b(?:let'?s|together|calm|fair|work (?:this|it) out|no problem|i can see)\b"),
    O('Feel understood.', 'The learner shows understanding of the concern.', 'I understand this client briefing really matters.', ['Do you know what is at stake for me?', 'You have no idea how much pressure I am under.'],
      "Show me that you understand why this matters to me. Ask me about it, or say: I understand that.", 'Understanding their reason, even if you disagree with their approach.', 'Defending your booking first', 'Say: I understand that, plus their reason.', 'I understand this client briefing really matters to you.', 'Say: I understand.', 'empathy', desc='Show understanding of their concern', signal=r"\b(?:i understand|i appreciate|i can see why|that sounds|must be|sorry|concern|why (?:is|does) (?:this|it))\b"),
    O('Find a solution.', 'The learner proposes a specific solution that works for both sides.', 'What if we swap: you take it at ten, and we move to the other slot?', ['So what do you suggest?', 'How do we fix this, then?'],
      'Now suggest a solution that works for both of us. You can use the option in your brief. Start with: What if we.', 'A specific plan that meets both needs.', 'Giving in completely, or refusing completely', 'Say: What if we, and what each side gets.', 'What if you take it at ten, and we use the small room?', 'Say: What if we.', 'problem solving', desc='Propose a fair, specific solution', signal=r"\b(?:what if|could|option|solution|how about|we could|i propose|instead|swap)\b")],
   'Okay. That works. Thanks for sorting this out with me.',
   [{'name': 'Adeel', 'resource': 'the main meeting room', 'your_use': 'a team workshop at 10', 'their_use': 'a client briefing at 10', 'alternative': 'The small room is free at 10 and the main room is free at 11.', 'need': 'A very important client is flying in, and only has one hour.'},
    {'name': 'Claire', 'resource': 'the testing environment', 'your_use': 'your release checks today', 'their_use': 'an urgent bug fix today', 'alternative': 'Your checks could run this evening instead, if someone stays late.', 'need': 'A customer is unable to log in, and the bug fix is needed to restore access.'}]),

 L('activity-interviews', 'interview', 'intermediate', 'A fictional job interview for a {{role}} role.',
   'You are interviewing for a {{role}} role with {{name}}. {{name}} wants a real example of {{focus}}. Use your own experience.',
   'Welcome. Thanks for coming in. Could you tell me about a time when you dealt with {{focus}}?',
   'Job candidate', 'You are a candidate in a job interview.', 'Give a relevant real example, explain the situation, what you did and the result, and answer confidently.',
   '{{name}} has a specific, relevant example, and knows what you did and what happened.',
   [A('{{name}}', 'Hiring manager', 'Would be your manager', 'Evidence that you can do this job.', 'Polite and attentive, and probes vague answers.', PRO, ["Ask 'what did you do personally?'", "Ask 'what was the result?'", 'Never supply the details of the example'], ['role', 'team', 'experience', 'job'])],
   ['The role is {{role}}.', "The candidate's examples come from their own experience. {{name}} knows only what the candidate says.", ('The role involves a lot of {{focus}}.', 'p1')],
   [O('Hear a relevant example.', 'The learner offers a relevant real example, and sets the context.', 'In my last job, a customer was unhappy about a late order.', ["Can you think of a specific time?", "Tell me about one real situation."],
      "It's a job interview. Tell me about one real time from your own experience. Start with: In my last job.", 'One real, relevant situation.', 'Talking in general', 'Choose one real situation. Start with when and where.', 'In my last job, a customer was unhappy about a late order.', 'Say: In my last job.', 'relevance', desc='Give a relevant example', signal=r"\b(?:in my (?:last|previous|current)|at my|when i|last year|one time|for example|situation|project)\b"),
    O('Hear personal action and the result.', 'The learner explains their own actions and the result.', 'I called the customer and fixed it, and they stayed with us.', ['What did you do yourself?', 'And what was the result?'],
      'Now tell me what you did, and what happened. Use: I did, and: the result was.', 'Your own actions, then a real result.', "Only saying 'we'", "Say 'I' for what you did, and end with the result.", 'I called the customer and fixed it, and as a result they stayed with us.', 'Say: I, and one action.', 'STAR evidence', desc='Explain your actions and the result', signal=r"\b(?:i (?:did|led|created|worked|called|built|decided|fixed|spoke|changed|made|took)|as a result|the result|in the end)\b"),
    O('Hear a confident close.', 'The learner connects this to the role with confidence.', 'I can bring that same approach to this role.', ['Why does that matter for this role?', 'How would that help you here?'],
      'Now connect your example to this job. Start with: I can bring that to this role because.', 'A plain statement of what you can do.', 'Undermining yourself: I am not sure, but', 'Say: I can, and how it helps this job.', 'I can bring that same approach to this role.', 'Say: I can.', 'confidence', desc='Connect your strengths to the role', signal=r"\b(?:i can|i will|i have|i would bring|this role|this job|i bring)\b")],
   'Thank you. That is exactly what I wanted to hear about.',
   [{'name': 'Mina', 'role': 'customer success', 'focus': 'a dissatisfied customer'}, {'name': 'George', 'role': 'project coordination', 'focus': 'conflicting priorities'}]),

 L('activity-storytelling', 'panel', 'intermediate', 'A fictional meeting with a prospective customer who wants to hear how your team works.',
   '{{name}} is considering working with your company, and asks for a true story that shows {{value}}. Tell a short professional story from your own work or studies. Do not invent achievements.',
   "Before we decide, I'd love to hear a real story that shows how you handle {{value}}.",
   'Company representative', 'You are telling a prospective customer a true professional story.', 'Tell a clear story with a beginning, middle and end, include real details, and say why it matters to them.',
   '{{name}} remembers your story and understands what it says about {{value}}.',
   [A('{{name}}', 'Prospective customer', 'Is deciding whether to work with your company', 'To see what your company is really like when things get difficult.', 'Interested and slightly sceptical of sales talk.', PRO, ['Ask what happened next', "Ask 'what does that mean for me?'", 'Never supply details of the story'], ['story', 'customer', 'company', 'problem'])],
   ['{{name}} wants a true story that shows {{value}}.', 'The story comes from the speaker. {{name}} knows only what the speaker says.', ('{{name}} is comparing two suppliers.', 'p1')],
   [O('Hear a story with a shape.', 'The learner tells events in order, with a beginning and a turning point.', 'Last year we had a client whose launch was at risk. Then...', ['So what happened?', 'Where does the story start?'],
      'Tell me a true story from your work or studies. Start with when it happened, and what went wrong.', 'A clear beginning, a problem and what came next.', 'Listing facts about your company', 'Start with a time and a problem.', 'Last year, a client\'s launch was at risk. Then we...', 'Say: Last year.', 'narrative', desc='Tell a story with a clear beginning and end', signal=r"\b(?:last (?:year|month|week)|when (?:we|i)|one day|then|after that|finally|in the end)\b"),
    O('Hear real detail.', 'The learner includes a concrete detail or evidence.', 'We had three days, and the file was missing.', ['Can you be more specific?', 'What exactly did you do?'],
      'Add a real detail from your story: a number, a name or something somebody said.', 'One real detail makes a story believable.', 'Inventing achievements', 'Use one real, specific detail.', 'We had three days, and we called the client each morning.', 'Say one real detail.', 'evidence', desc='Include real, specific detail', signal=r"\b(?:for example|\d+|days?|weeks?|because|exactly|data|result)\b"),
    O('Hear why it matters.', 'The learner connects the story to the listener.', 'What that means for you is that you will always get a straight answer.', ['So what does that mean for me?', 'Why are you telling me this?'],
      'Finish by saying why this story matters to me. Start with: What that means for you is.', 'Ending with the point for this listener.', 'Stopping when the events stop', 'Say: What that means for you is.', 'What that means for you is that you will always know where things stand.', 'Say: What that means for you.', 'impact', desc='Say why it matters to the listener', signal=r"\b(?:means for you|for you|that'?s why|the lesson|what (?:this|that) (?:shows|means)|so you)\b")],
   'Thank you. That helps me a lot more than a brochure would.',
   [{'name': 'Hannah', 'value': 'trust when something goes wrong'}, {'name': 'Salman', 'value': 'reliability under pressure'}]),

 L('activity-critical-thinking', 'meeting', 'intermediate', 'A fictional review with a project sponsor who wants to act on two reports.',
   '{{name}}, the project sponsor, says that {{claim}}. Your figures: {{good}}, but also {{bad}}. {{unknown}} Test the assumptions, weigh the evidence, and say what you would do.',
   "The report says {{claim}}. That proves it's working, so I want to roll it out everywhere. You agree, don't you?",
   'Analyst', 'You are an analyst reviewing evidence with a project sponsor.', 'Question the assumption, weigh both pieces of evidence, and give a reasoned judgement on what to do next.',
   '{{name}} sees why the conclusion is not yet safe, and has a clear recommendation from you.',
   [A('{{name}}', 'Project sponsor', 'Owns the project budget', 'To make a quick decision that can be defended.', 'Keen, in a hurry, and fair when shown evidence.', PRO, ['Push for a quick yes', "Ask 'so what would you do?'", 'Accept a well-reasoned recommendation'], ['report', 'data', 'evidence', 'decision', 'rollout'], 'Promised the board an update this month.')],
   ['The report says {{claim}}.', 'The figures show {{good}}.', 'The figures also show {{bad}}.', '{{unknown}}'],
   [O('Have the assumption challenged.', 'The learner questions an assumption, or looks for alternative explanations.', "That assumes the change caused it. Could something else explain it?", ['So you agree that it is working?', 'What is wrong with that conclusion?'],
      "I've jumped to a conclusion. Question it. You can ask: Could something else explain it?", 'Asking what else could explain the result.', 'Accepting the headline', 'Ask: What are we assuming? What else could explain it?', 'That assumes the change caused it. Could something else explain it?', 'Ask: Could something else explain it?', 'analysis', desc='Question the assumption', signal=r"\b(?:assum|could (?:something|there|it)|alternative|compare|what else|cause|because of|risk)\b"),
    O('Weigh the evidence.', 'The learner uses both pieces of evidence.', 'The data shows one thing improved, but the other got worse.', ['What does the data actually tell us?', 'Which number do you trust?'],
      'Look at both figures in your brief. Tell me what they show together.', 'Looking at all the evidence, including what doesn\'t fit.', 'Quoting only the helpful number', 'Say: The data shows, and: but.', 'The data shows one figure improved, but the other got worse.', 'Say: The data shows.', 'evidence', desc='Weigh all of the evidence', signal=r"\b(?:data|evidence|figures?|numbers?|shows?|however|but also|measured|percent)\b"),
    O('Hear a judgement.', 'The learner makes a reasoned recommendation.', "I recommend a small test before rolling out, because the evidence is mixed.", ['So what would you do?', 'I need a decision. What do you recommend?'],
      'Now tell me what you would do, and why. Start with: I recommend.', 'A clear decision, even with incomplete evidence.', 'Saying only: We need more data', 'Say: I recommend, then: because.', 'I recommend a small test first, because the evidence is mixed.', 'Say: I recommend.', 'judgement', desc='Give a reasoned recommendation', signal=r"\b(?:i recommend|i would|i suggest|we should|my (?:view|judgement)|therefore|best)\b")],
   "Fair enough. That's a stronger position than the one I walked in with.",
   [{'name': 'Zara', 'claim': 'the new training raised sales by 10 percent', 'good': 'sales rose by 10 percent in the trained team', 'bad': 'repeat purchases fell by 6 percent', 'unknown': 'A seasonal promotion ran at the same time, and nobody has separated its effect.'},
    {'name': 'Andrew', 'claim': 'the new system improved response times by 20 percent', 'good': 'average response time improved by 20 percent', 'bad': 'customer satisfaction fell by 5 points', 'unknown': 'The team also reduced the number of questions it answers per ticket.'}]),

 L('activity-social-engineering', 'colleague', 'intermediate', 'A fictional unexpected phone call at work, as a practice exercise in spotting manipulation.',
   'An unknown caller, {{name}}, says they are {{claim}}, and urgently wants {{asks}}. This is a simulation. Spot the warning signs, verify using an approved channel, and report it.',
   "Hi, this is {{name}}, {{claim}}. This is urgent. I need {{asks}} right now, or {{threat}}.",
   'Employee', 'You are an employee who gets a suspicious phone call.', 'Recognize the warning signs, refuse politely and verify through an approved channel, and say you will report it.',
   'You gave nothing away, you verified through a proper channel, and you said you will report it.',
   [A('{{name}}', 'Caller', 'Claims to be {{claim}}; this is a practice simulation', 'To get {{asks}} by creating pressure.', 'Friendly, then urgent, then a little annoyed. Never abusive.', 'Confident, plausible, hurried business English.', ['Create urgency', 'Name-drop a senior person', 'Say the usual checks have been waived'], ['urgent', 'password', 'manager', 'system', 'bank'])],
   ['This is a simulation about a suspicious caller.', 'The caller claims to be {{claim}} and asks for {{asks}}.', "The company's rule: never share {{asks}} by phone, and verify through {{channel}}.", 'Suspicious calls are reported to the security team.'],
   [O('See whether the warning signs are noticed.', 'The learner recognizes or names something suspicious.', "This seems unusual. I can't share that by phone.", ['Come on, this is really urgent.', 'Your manager already approved this.'],
      "This is a practice exercise. I'm a suspicious caller. Tell me you can't share that, or say what seems wrong.", 'Noticing urgency, pressure and unusual requests.', 'Giving in to pressure', "Say: I can't share that by phone.", "This seems unusual, and I can't share that by phone.", "Say: I can't share that.", 'risk recognition', desc='Recognize the warning signs', signal=r"\b(?:suspicious|unusual|can'?t share|cannot share|not able to|won'?t|urgent|phishing|not allowed|don'?t share|strange)\b"),
    O('See whether verification is insisted on.', 'The learner insists on verifying through an approved channel.', "I'll verify this with {{channel}} first.", ['Can you not just do it, this once?', 'There is no time to check.'],
      "Now say how you'll check who I am. Use the approved channel in your brief. Start with: I will verify this.", 'Using a channel you trust, not one the caller gives you.', 'Calling a number given by the caller', 'Say: I will verify this through, and the official channel.', "I'll verify this with {{channel}} first.", 'Say: I will verify this.', 'verification', desc='Verify through an approved channel', signal=r"\b(?:verify|check|confirm|official|call back|approved|independent)\b"),
    O('See whether it is reported.', 'The learner says they will report the call.', "I'm going to report this call to our security team.", ['There is no need to tell anyone about this.', 'Please keep this between us.'],
      'One more thing to do: tell me that you will report this call.', 'Reporting even if nothing was lost.', 'Thinking it does not matter, since you said no', 'Say: I will report this to security.', "I'm going to report this call to our security team.", 'Say: I will report this.', 'reporting', desc='Report the incident', signal=r"\b(?:report|security|incident|escalate|my manager|tell (?:it|security))\b")],
   'Fine. Goodbye. (Practice complete: that caller was part of the simulation.)',
   [{'name': 'Kevin', 'claim': 'from IT support', 'asks': 'your password', 'threat': 'your account will be locked', 'channel': 'the IT help desk number on the intranet'},
    {'name': 'Dina', 'claim': 'from your supplier\'s accounts team', 'asks': 'the bank details on file changed to a new account', 'threat': 'your next delivery will be stopped', 'channel': 'the supplier contact in the company records'}]),

 L('activity-email-professionalism', 'colleague', 'intermediate', 'A fictional office chat in which a colleague reviews an email as it is drafted.',
   'You need to email {{to}} about {{topic}}. The facts: {{facts_text}} {{name}} sits next to you and offers to look at it. Say or type your email piece by piece: subject, polite explanation, the action you want, and a closing.',
   "Okay, you need to email {{to}} about {{topic}}. What's your subject line going to be?",
   'Colleague', 'You are drafting a professional email while a colleague helps.', 'Write a clear subject line, explain politely in a sentence or two, request a specific action, and close professionally.',
   'Your draft has a clear subject, a polite explanation, a clear request and a closing.',
   [A('{{name}}', 'Colleague', 'Sits next to you and has offered to read your draft', 'To help you send something clear the first time.', 'Friendly and practical. Reacts as the reader would.', 'Natural workplace English. Short comments.', ["React as the reader would: 'would they know what you want?'", 'Do not write the email for them'], ['email', 'subject', 'reader', 'tone'])],
   ['The email is to {{to}} about {{topic}}.', 'The facts: {{facts_text}}'],
   [O('See the subject line.', 'The learner gives a specific subject line.', 'Subject: Delivery delayed until Friday', ["What's your subject line?", 'Would they know what this is about from the subject alone?'],
      "We're drafting your email. Tell me the subject line. Make it say exactly what the email is about.", 'A subject line that says what the email is about.', "'Hello' or 'Important' as a subject", 'Say the main fact in a few words.', 'Subject: Delivery delayed until Friday', 'Say: Subject, and the main fact.', 'subject clarity', desc='Write a clear subject line', signal=r"\bsubject\b"),
    O('See the polite explanation.', 'The learner writes a polite, clear explanation.', 'Dear Ms Khan, I am sorry to tell you that your delivery is delayed.', ['Okay, how does it start?', 'What do you say first?'],
      'Now give me the greeting and explanation. Start with: Dear, or: Hello.', 'A greeting and a short, polite explanation.', 'Too casual, or a long apology', "Start: Dear, then say what happened, politely.", 'Dear Ms Khan, I am sorry to tell you that your delivery is delayed.', 'Say: Dear, and the name.', 'tone', desc='Explain politely', signal=r"\b(?:dear|hello|hi |sorry|please|thank|regards|i am writing|i'?m writing)\b"),
    O('See the request and closing.', 'The learner requests a specific action and closes professionally.', 'Please confirm by Thursday. Kind regards, Sara', ['So what do you want them to do?', 'How do you end it?'],
      'Now tell them what you need them to do, by when, and finish with a closing. For example: Please confirm by Thursday. Kind regards.', 'One clear request, with a date, and a polite closing.', 'Ending with no request', 'Say: Please, and a date. Then: Kind regards.', 'Please confirm by Thursday. Kind regards, Sara', 'Say: Please confirm by.', 'requested action', desc='Request an action and close', signal=r"\b(?:please|could you|confirm|reply|send|kind regards|best regards|by (?:monday|tuesday|wednesday|thursday|friday|tomorrow))\b")],
   "Looks good. I'd send that.",
   [{'name': 'Nadia', 'to': 'a customer, Ms Khan', 'topic': 'a late delivery', 'facts_text': 'the delivery moves from Tuesday to Friday, and she needs to confirm that someone will be home.'},
    {'name': 'Chris', 'to': 'your manager, Mr Ali', 'topic': 'a changed appointment', 'facts_text': 'the supplier visit moves from Monday to Wednesday at 2 pm, and you need him to confirm that he can attend.'}]),
]
